// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    address owner = address(0xABCD);

    function setUp() public {
        c = new DepositLog();
    }

    function testFuzz_property(address a, bool wantTrue) public {
        if (wantTrue) {
            vm.prank(address(0));
            c.setApprovedLogger(a, true);
            bool mappingVal = c.approvedLoggers(a);
            (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.approvedToLog.selector, a));
            require(ok, "approvedToLog reverted");
            bool retVal = abi.decode(ret, (bool));
            assertTrue(!mappingVal || retVal);
            return;
        } else {
            bool mappingVal = c.approvedLoggers(a);
            (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.approvedToLog.selector, a));
            require(ok, "approvedToLog reverted");
            bool retVal = abi.decode(ret, (bool));
            assertTrue(!mappingVal || retVal);
            return;
        }
    }
}
